/*
 * TikuOS kits -- the foundation TikuDesktop and TikuTracker
 * both stand on.
 *
 * Authors: Ambuj Varshney <ambuj@tiku-os.org>
 *
 * tiku_font.h - the UI faces, baked or read from font files.
 *
 * Baked glyphs are 8-bit coverage maps generated by
 * kits/interface/tools/genfont.py; a face read from a file is rasterised
 * here.  Text is antialiased like R5's, with no font library underneath.
 *
 * SPDX-License-Identifier: Apache-2.0
 */
#ifndef TIKU_FONT_H_
#define TIKU_FONT_H_
#ifdef TIKU_DISPLAYLESS
/* A build with no pixels, a board's, takes these names from the
 * recorder's tiku_font.h on its include path; the declarations below are
 * for builds that paint. */
#include <tiku_font.h>
#else

#include "tiku_gfx.h"

/** @brief One baked glyph: its coverage map and where it sits. */
typedef struct {
    short cp;          /* code point            */
    short adv;         /* advance width         */
    short w, h;        /* coverage map size     */
    short ox, oy;      /* offset from the pen   */
    int   off;         /* index into the blob   */
} tiku_glyph_t;

/**
 * @brief Where a face's glyphs come from, when they are not baked.
 *
 * A face read from a file rasterises what it is asked for and keeps it,
 * so a dropped font draws any letter it has (Greek, Cyrillic, kana).
 */
typedef struct tiku_face_src tiku_face_src_t;

/** @brief A face: its glyphs and metrics, baked or read from a file. */
typedef struct tiku_font {
    const tiku_glyph_t *glyphs;
    const unsigned char     *bits;
    int                      count;
    int                      height;   /* ascent + descent */
    int                      ascent;
    int                      first;
    /* The same face at twice the pixel size, advances forced to exactly
     * double, so a scaled surface can draw finer detail into the layout
     * the logical metrics measured.  NULL on the 2x faces. */
    const struct tiku_font *hi;
    /*
     * NULL for a baked face; otherwise the file its glyphs are drawn
     * from and the cache they are kept in.  Last in the struct because
     * the generated tables initialise the fields above it by position,
     * and a baked face leaves it zero.  The cache is changed through this
     * pointer while the face itself stays const, as every caller holds it.
     */
    tiku_face_src_t        *src;
} tiku_font_t;

/**
 * @brief Choose the UI text size in pixels.
 *
 * Snaps down to the nearest baked size (10, 12, 14 or 16 px; below 10
 * takes 10).  The pointers already handed out follow the
 * change, so everything laid out from font metrics resizes on its next
 * paint.
 *
 * @return the size actually chosen.
 */
int tiku_font_set_size(int px);

/** @brief The size currently in force. */
int tiku_font_size(void);

/** @brief The UI face at the chosen size (12 px until told otherwise). */
const tiku_font_t *tiku_font_plain(void);

/** @brief How many interface families the toolkit carries. */
int tiku_font_family_count(void);

/** @brief What family @p family is called, or NULL past the last. */
const char *tiku_font_family_name(int family);

/**
 * @brief Choose the family the interface is drawn in.
 *
 * Every family is baked at the same four sizes and within a pixel of the
 * reference face's height, so a switch changes the letters and not the
 * layout.  Out-of-range asks keep the family in force.
 *
 * @return the family actually chosen.
 */
int tiku_font_set_family(int family);

/** @brief The family in force. */
int tiku_font_family(void);
/** @brief Family/source configuration token, unchanged by text size changes. */
unsigned tiku_font_generation(void);

/** @brief What the family in force is called, baked or dropped in. */
const char *tiku_font_current_family(void);

/**
 * @brief Draw the interface with faces read from files.
 *
 * For fonts a person dropped in the fonts folder; the files are parsed
 * and rasterised here.  @p bold may be NULL, or fail to read, and then
 * the one face does both weights.
 *
 * @return 1 when @p regular could be read; nothing changes when it could
 *         not.
 */
int tiku_font_set_files(const char *regular, const char *bold);

/** @brief Go back to the baked families. */
void tiku_font_use_baked(void);

/*
 * The metric-reference rule: all layout is computed against the plain
 * face's metrics, and every other face the toolkit offers, bold or sized,
 * must live within them (height within two pixels).  The assertion that
 * holds it is in tests/system/test_background.c.
 */

/** @brief The bold face, for window titles and default-button labels. */
const tiku_font_t *tiku_font_bold(void);

/**
 * @brief The plain face at @p px, or the nearest smaller one (the
 *        smallest below that), without changing the UI size.
 *
 * For chrome that wants a face other than the body's, such as a column
 * title strip; the UI size stays as it is.
 */
const tiku_font_t *tiku_font_at(int px);
/** @brief Resolve a measurement face number, including encoded CSS fonts. */
const tiku_font_t *tiku_font_for_measure(int face);

/**
 * @brief A face whose every glyph advances the same width.
 *
 * For grid views such as the terminal and the code view; the interface
 * itself is laid out against the proportional face.  Its size follows the
 * desktop's font size.
 *
 * @param bold Nonzero for the heavier face.
 */
const tiku_font_t *tiku_font_mono(int bold);

/**
 * @brief The pixel size of the face tiku_font_mono() gives now.
 *
 * @return 13 below desktop font size 14, else 15
 */
int tiku_font_mono_px(void);

/**
 * @brief The baked mono face at @p px, or the nearest smaller one.
 *
 * The ladder runs from 9 to 23 pixels in odd steps, and a size under 9
 * takes the 9.  The desktop's font size plays no part, and the face
 * travels through a display list at its own size.
 *
 * @param px   Wanted size in pixels
 * @param bold Nonzero for the heavier face.
 */
const tiku_font_t *tiku_font_mono_at(int px, int bold);

/**
 * @brief The mono face a display-list face ID from TIKU_DL_MONO_SIZED
 *        names, or NULL for any other ID.
 *
 * @param id A face ID read from a display list
 */
const tiku_font_t *tiku_font_mono_stream(unsigned id);

/** @brief The advance every glyph of the mono face has. */
int tiku_font_mono_cell(int bold);

/* The cuts tiku_font_styled() is asked for. */
#define TIKU_FONT_BOLD   0x1u
#define TIKU_FONT_ITALIC 0x2u

/**
 * @brief The cut of @p f's family and size in @p style, or NULL when the
 *        toolkit has none.
 *
 * Every baked face and the pair in force have a bold cut; only the mono
 * faces have italic ones, on the same advance as their upright cut.
 * @p style 0 is the upright regular cut.
 */
const tiku_font_t *tiku_font_styled(const tiku_font_t *f, unsigned style);

/** @brief Pixel width of @p text. */
int tiku_text_width(const tiku_font_t *f, const char *text);

/**
 * @brief How far tiku_text() moves its pen for code point @p cp.
 *
 * A letter the face lacks answers the advance drawing it would use, so a
 * caller that measures text a code point at a time gets the same widths
 * as tiku_text_width() and the same pen positions as tiku_text().
 */
int tiku_text_advance(const tiku_font_t *f, unsigned cp);

/** @brief Line height (ascent + descent). */
int tiku_text_height(const tiku_font_t *f);

/**
 * @brief Draw @p text with its baseline at @p y, left edge at @p x.
 *
 * Coverage is blended against whatever is already on the surface, so text on a
 * bevel or a selection stripe antialiases into the right background.
 */
void tiku_text(tiku_surface_t *s, const tiku_font_t *f,
                    int x, int y, const char *text, tiku_rgb_t c);

/**
 * @brief Draw @p text centred in @p r (both axes).
 *
 * @return The x the text started at, so callers can align related art.
 */
int tiku_text_centered(tiku_surface_t *s, const tiku_font_t *f,
                            tiku_rect_t r, const char *text,
                            tiku_rgb_t c);

#endif /* TIKU_DISPLAYLESS */
#endif /* TIKU_FONT_H_ */
